+// buildFeatureSnapshot reconstructs a FeatureSnapshot from the database rows.
+func buildFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f database.WorkspaceFeature) (domain.FeatureSnapshot, error) {
+	docs, err := q.ListFeatureDocuments(ctx, database.ListFeatureDocumentsParams{
+		WorkspaceID: uid,
+		FeatureID:   f.FeatureID,
+	})
+	if err != nil {
+		return domain.FeatureSnapshot{}, dbErr("list docs for snapshot", err)
+	}
+
+	tasks, err := q.ListFeatureTasks(ctx, database.ListFeatureTasksParams{
+		WorkspaceID: uid,
+		FeatureID:   f.FeatureID,
+	})
+	if err != nil {
+		return domain.FeatureSnapshot{}, dbErr("list tasks for snapshot", err)
+	}
+
+	docSnaps := make([]domain.DocumentSnapshot, 0, len(docs))
+	for _, d := range docs {
+		ds := domain.DocumentSnapshot{
+			DocumentType: d.DocumentType,
+			SourcePath:   d.SourcePath,
+		}
+		if d.URL != nil {
+			ds.URL = *d.URL
+		}
+		docSnaps = append(docSnaps, ds)
+	}
+
+	taskSnaps := make([]domain.TaskSnapshot, 0, len(tasks))
+	for _, t := range tasks {
+		taskSnaps = append(taskSnaps, rowToTaskSnapshot(t))
+	}
+
+	fs := domain.FeatureSnapshot{
+		FeatureID:  f.FeatureID,
+		Title:      f.Title,
+		SourcePath: f.SourcePath,
+		Documents:  docSnaps,
+		Tasks:      taskSnaps,
+	}
+	if f.FeatureStatus != nil {
+		fs.Status = *f.FeatureStatus
+	}
+	if f.CurrentStage != nil {
+		fs.CurrentStage = *f.CurrentStage
+	}
+	if f.NextAction != nil {
+		fs.NextAction = *f.NextAction
+	}
+	if f.SourceHash != nil {
+		fs.SourceHash = *f.SourceHash
+	}
+	return fs, nil
+}
+
+// rowToTaskSnapshot converts a database row to a domain.TaskSnapshot.
+func rowToTaskSnapshot(t database.WorkspaceTask) domain.TaskSnapshot {
+	ts := domain.TaskSnapshot{
+		TaskID:     t.TaskID,
+		FeatureID:  t.FeatureID,
+		Title:      t.Title,
+		SourcePath: t.SourcePath,
+	}
+	if t.Repo != nil {
+		ts.Repo = *t.Repo
+	}
+	if t.Status != nil {
+		ts.Status = *t.Status
+	}
+	if t.BlockedReason != nil {
+		ts.BlockedReason = *t.BlockedReason
+	}
+	if t.Branch != nil {
+		ts.Branch = *t.Branch
+	}
+	if t.SourceHash != nil {
+		ts.SourceHash = *t.SourceHash
+	}
+	ts.DependsOn = unmarshalStringSlice(t.DependsOn)
+	if len(t.Execution) > 0 {
+		var m map[string]interface{}
+		_ = json.Unmarshal(t.Execution, &m)
+		ts.Execution = m
+	}
+	if len(t.Pr) > 0 {
+		var m map[string]interface{}
+		_ = json.Unmarshal(t.Pr, &m)
+		ts.PR = m
+	}
+	if len(t.WorkspacePr) > 0 {
+		var m map[string]interface{}
+		_ = json.Unmarshal(t.WorkspacePr, &m)
+		ts.WorkspacePR = m
+	}
+	return ts
+}
